        <Carousel
          opts={{
            align: "start",
            dragFree: true,
          }}
        >
          <CarouselContent>
            {DATA.map((item) => (
              <CarouselItem
                key={item.id}
                className="min-w-[350px] flex-1 cursor-pointer"
              >
                <a href={item.href} target="_self" className="group">
                  <div className="relative overflow-hidden rounded-2xl">
                    <img
